"""Exception hierarchy for microdb."""

from __future__ import annotations


class MicroDBError(Exception):
    """Base class for every error raised by microdb."""


class LexError(MicroDBError):
    def __init__(self, message: str, offset: int) -> None:
        super().__init__(f"{message} (at offset {offset})")
        self.offset = offset


class ParseError(MicroDBError):
    def __init__(self, message: str, offset: int) -> None:
        super().__init__(f"{message} (at offset {offset})")
        self.offset = offset


class SchemaError(MicroDBError):
    pass


class TypeMismatchError(MicroDBError):
    pass


class UnknownColumnError(MicroDBError):
    pass


class AmbiguousColumnError(MicroDBError):
    pass


class UnknownTableError(MicroDBError):
    pass


class UnknownFunctionError(MicroDBError):
    pass


class ArityError(MicroDBError):
    pass


class AggregateError(MicroDBError):
    pass


class GroupingError(MicroDBError):
    pass

"""Value model: type classification, three-valued logic, comparison and arithmetic."""

from __future__ import annotations

from .errors import TypeMismatchError

TYPE_NAMES = ("INT", "FLOAT", "TEXT", "BOOL")


def type_of(v: object) -> str:
    if v is None:
        return "NULL"
    if isinstance(v, bool):
        return "BOOL"
    if isinstance(v, int):
        return "INT"
    if isinstance(v, float):
        return "FLOAT"
    if isinstance(v, str):
        return "TEXT"
    raise TypeMismatchError(f"unsupported Python value {v!r}")


def is_numeric(v: object) -> bool:
    return isinstance(v, (int, float)) and not isinstance(v, bool)


def is_logical(v: object) -> bool:
    return v is None or isinstance(v, bool)


# --- three-valued logic -------------------------------------------------------


def and_(a: bool | None, b: bool | None) -> bool | None:
    if a is False or b is False:
        return False
    if a is None or b is None:
        return None
    return True


def or_(a: bool | None, b: bool | None) -> bool | None:
    if a is True or b is True:
        return True
    if a is None or b is None:
        return None
    return False


def not_(a: bool | None) -> bool | None:
    if a is None:
        return None
    return not a


# --- comparison ---------------------------------------------------------------


def _check_comparable(a: object, b: object) -> None:
    ta, tb = type_of(a), type_of(b)
    if is_numeric(a) and is_numeric(b):
        return
    if ta == tb and ta in ("TEXT", "BOOL"):
        return
    raise TypeMismatchError(f"cannot compare {ta} with {tb}")


def compare_eq(a: object, b: object) -> bool | None:
    if a is None or b is None:
        return None
    _check_comparable(a, b)
    return a == b


def compare_lt(a: object, b: object) -> bool | None:
    if a is None or b is None:
        return None
    _check_comparable(a, b)
    return a < b


def compare(a: object, b: object) -> int:
    """Total ordering of two non-NULL values: -1, 0 or 1."""
    if compare_lt(a, b):
        return -1
    if compare_lt(b, a):
        return 1
    return 0


# --- arithmetic ---------------------------------------------------------------


def _require_numeric(op: str, v: object) -> None:
    if not is_numeric(v):
        raise TypeMismatchError(f"operator {op!r} requires numeric operands, got {type_of(v)}")


def arith(op: str, a: object, b: object) -> object:
    if op not in "+-*/%" or len(op) != 1:
        raise ValueError(f"unknown arithmetic operator {op!r}")
    if a is None or b is None:
        return None
    _require_numeric(op, a)
    _require_numeric(op, b)
    if op == "+":
        return a + b
    if op == "-":
        return a - b
    if op == "*":
        return a * b
    if op == "/":
        if b == 0:
            return None
        return a / b
    if not (isinstance(a, int) and isinstance(b, int)):
        raise TypeMismatchError("operator '%' requires INT operands")
    if b == 0:
        return None
    return a % b


def negate(a: object) -> object:
    if a is None:
        return None
    _require_numeric("-", a)
    return -a


def concat(*args: object) -> object:
    """Concatenate TEXT values; NULL if any argument is NULL."""
    for v in args:
        if v is not None and not isinstance(v, str):
            raise TypeMismatchError(f"concat requires TEXT arguments, got {type_of(v)}")
    if any(v is None for v in args):
        return None
    return "".join(args)  # type: ignore[arg-type]


def hash_key(v: object) -> tuple:
    """A hashable key under which 1, 1.0 collide but True and 1 do not.

    Used for GROUP BY and DISTINCT, where NULL is equal to NULL.
    """
    if v is None:
        return ("NULL",)
    if is_numeric(v):
        return ("NUM", v)
    return (type_of(v), v)

"""Schema layer: Column and Table."""

from __future__ import annotations

import dataclasses

from .errors import SchemaError
from .value import TYPE_NAMES, type_of


@dataclasses.dataclass(frozen=True)
class Column:
    name: str
    type: str


def coerce_cell(value: object, col: Column, row_index: int) -> object:
    """Validate one cell against its column type; FLOAT columns widen int."""
    if value is None:
        return None
    kind = type_of(value)
    if kind == col.type:
        return value
    if col.type == "FLOAT" and kind == "INT":
        return float(value)
    raise SchemaError(
        f"row {row_index}: column {col.name!r} expects {col.type}, got {kind} {value!r}"
    )


class Table:
    def __init__(self, name: str, columns: list[Column], rows: list[list[object]]) -> None:
        if not columns:
            raise SchemaError(f"table {name!r} has no columns")
        seen: set[str] = set()
        for col in columns:
            if col.name in seen:
                raise SchemaError(f"duplicate column {col.name!r} in table {name!r}")
            seen.add(col.name)
            if col.type not in TYPE_NAMES:
                raise SchemaError(f"column {col.name!r} has unknown type {col.type!r}")
        checked: list[list[object]] = []
        for i, row in enumerate(rows):
            if len(row) != len(columns):
                raise SchemaError(
                    f"row {i} has {len(row)} values, expected {len(columns)}"
                )
            checked.append([coerce_cell(v, c, i) for v, c in zip(row, columns)])
        self._name = name
        self._columns = list(columns)
        self._rows = checked
        self._index = {c.name: i for i, c in enumerate(columns)}

    @property
    def name(self) -> str:
        return self._name

    @property
    def columns(self) -> list[Column]:
        return self._columns

    @property
    def rows(self) -> list[list[object]]:
        return self._rows

    def column_index(self, name: str) -> int:
        try:
            return self._index[name]
        except KeyError:
            raise SchemaError(f"unknown column {name!r} in table {self._name!r}") from None

    def __repr__(self) -> str:
        return f"Table({self._name!r}, {len(self._columns)} columns, {len(self._rows)} rows)"

"""Tokenizer for the microdb query language."""

from __future__ import annotations

import dataclasses

from .errors import LexError

KEYWORDS = frozenset(
    "SELECT DISTINCT FROM INNER LEFT JOIN ON WHERE GROUP BY HAVING ORDER ASC DESC "
    "LIMIT OFFSET AS AND OR NOT IS NULL TRUE FALSE".split()
)

TWO_CHAR_OPS = ("<>", "<=", ">=")
ONE_CHAR_OPS = "=<>+-*/%(),."


@dataclasses.dataclass(frozen=True)
class Token:
    kind: str  # INT FLOAT TEXT IDENT KW OP EOF
    value: object
    offset: int
    end: int


def _is_ident_start(ch: str) -> bool:
    return ch.isascii() and (ch.isalpha() or ch == "_")


def _is_ident_char(ch: str) -> bool:
    return ch.isascii() and (ch.isalnum() or ch == "_")


def _scan_number(src: str, pos: int) -> Token:
    n = len(src)
    i = pos
    is_float = False
    while i < n and src[i].isdigit():
        i += 1
    if i < n and src[i] == ".":
        is_float = True
        i += 1
        while i < n and src[i].isdigit():
            i += 1
    if i < n and src[i] in "eE":
        j = i + 1
        if j < n and src[j] in "+-":
            j += 1
        if j < n and src[j].isdigit():
            while j < n and src[j].isdigit():
                j += 1
            i = j
            is_float = True
    text = src[pos:i]
    if is_float:
        return Token("FLOAT", float(text), pos, i)
    return Token("INT", int(text), pos, i)


def _scan_text(src: str, pos: int) -> Token:
    n = len(src)
    i = pos + 1
    parts: list[str] = []
    while True:
        if i >= n:
            raise LexError("unterminated text literal", pos)
        ch = src[i]
        if ch == "'":
            if i + 1 < n and src[i + 1] == "'":
                parts.append("'")
                i += 2
                continue
            return Token("TEXT", "".join(parts), pos, i + 1)
        parts.append(ch)
        i += 1


def _scan_word(src: str, pos: int) -> Token:
    n = len(src)
    i = pos
    while i < n and _is_ident_char(src[i]):
        i += 1
    word = src[pos:i]
    if word.upper() in KEYWORDS:
        return Token("KW", word.upper(), pos, i)
    return Token("IDENT", word, pos, i)


def tokenize(src: str) -> list[Token]:
    tokens: list[Token] = []
    n = len(src)
    i = 0
    while i < n:
        ch = src[i]
        if ch.isspace():
            i += 1
            continue
        if src.startswith("--", i):
            nl = src.find("\n", i)
            i = n if nl < 0 else nl + 1
            continue
        if ch.isdigit() or (ch == "." and i + 1 < n and src[i + 1].isdigit()):
            tok = _scan_number(src, i)
        elif ch == "'":
            tok = _scan_text(src, i)
        elif _is_ident_start(ch):
            tok = _scan_word(src, i)
        elif src[i : i + 2] in TWO_CHAR_OPS:
            tok = Token("OP", src[i : i + 2], i, i + 2)
        elif ch in ONE_CHAR_OPS:
            tok = Token("OP", ch, i, i + 1)
        else:
            raise LexError(f"unexpected character {ch!r}", i)
        tokens.append(tok)
        i = tok.end
    tokens.append(Token("EOF", None, n, n))
    return tokens

"""Aggregate functions: count, sum, avg, min, max."""

from __future__ import annotations

from .errors import TypeMismatchError, UnknownFunctionError
from .value import compare_lt, is_numeric, type_of

AGGREGATE_NAMES = frozenset({"count", "sum", "avg", "min", "max"})


class Aggregator:
    """Accumulates values for one group. NULL inputs are ignored except by count(*)."""

    name = ""

    def add(self, value: object) -> None:
        raise NotImplementedError

    def result(self) -> object:
        raise NotImplementedError


class CountStar(Aggregator):
    name = "count"

    def __init__(self) -> None:
        self.n = 0

    def add(self, value: object) -> None:
        self.n += 1

    def result(self) -> object:
        return self.n


class Count(Aggregator):
    name = "count"

    def __init__(self) -> None:
        self.n = 0

    def add(self, value: object) -> None:
        if value is not None:
            self.n += 1

    def result(self) -> object:
        return self.n


class Sum(Aggregator):
    name = "sum"

    def __init__(self) -> None:
        self.total: object = None
        self.n = 0

    def add(self, value: object) -> None:
        if value is None:
            return
        if not is_numeric(value):
            raise TypeMismatchError(f"{self.name} requires numeric input, got {type_of(value)}")
        self.total = value if self.total is None else self.total + value  # type: ignore[operator]
        self.n += 1

    def result(self) -> object:
        return self.total


class Avg(Sum):
    name = "avg"

    def result(self) -> object:
        if self.n == 0:
            return None
        return float(self.total) / self.n  # type: ignore[arg-type]


class Extreme(Aggregator):
    """Shared implementation of min and max."""

    want_less = True

    def __init__(self) -> None:
        self.best: object = None

    def add(self, value: object) -> None:
        if value is None:
            return
        if self.best is None:
            self.best = value
            return
        lt = compare_lt(value, self.best)
        if lt is (True if self.want_less else False):
            self.best = value

    def result(self) -> object:
        return self.best


class Min(Extreme):
    name = "min"
    want_less = True


class Max(Extreme):
    name = "max"
    want_less = False


def make_aggregator(name: str, star: bool) -> Aggregator:
    lname = name.lower()
    if lname not in AGGREGATE_NAMES:
        raise UnknownFunctionError(f"unknown aggregate {name!r}")
    if star:
        return CountStar()
    factories: dict[str, type[Aggregator]] = {
        "count": Count,
        "sum": Sum,
        "avg": Avg,
        "min": Min,
        "max": Max,
    }
    return factories[lname]()

